const horarioFormatado = horario
  ? new Intl.DateTimeFormat('pt-BR', { timeZone: 'America/Sao_Paulo', hour: '2-digit', minute: '2-digit', hour12: false }).format(new Date(horario))
  : '';

const assuntos = {
  reuniao_amanha: `Confirmando nossa reunião de amanhã às ${horarioFormatado}`,
  reuniao_hoje: `Lembrete: nossa reunião é hoje às ${horarioFormatado}`,
  reuniao_proximos_10min: 'Começamos em instantes — segue o link',
};
const subject = assuntos[motivo] || 'Lembrete da nossa reunião';

const paragrafos = String(corpo || '')
  .split(/\n\s*\n/)
  .map((p) => p.trim())
  .filter(Boolean)
  .map((p) => {
    if (/^https?:\/\/\S+$/.test(p)) {
      return `<div style="text-align:center;margin:8px 0 16px 0;">
        <a href="${esc(p)}" style="display:inline-block;background:#0d2a4a;color:#ffffff;text-decoration:none;padding:14px 28px;border-radius:4px;font-family:Arial,Helvetica,sans-serif;font-size:14px;font-weight:600;letter-spacing:0.04em;">Entrar na reunião</a>
