    }
    return `<p style="margin:0 0 16px 0;font-family:Georgia,'Times New Roman',serif;font-size:14px;line-height:1.7;color:#1a2030;">${esc(p).replace(/\n/g, '<br/>')}</p>`;
  })
  .join('');

const html = `<!doctype html>
