        <tr><td style="background:#0d2a4a;padding:28px 32px;text-align:center;">
          <div style="font-family:Georgia,'Times New Roman',serif;color:#ffffff;font-size:20px;letter-spacing:0.08em;font-weight:600;">MONTEIRO RAMALHO</div>
          <div style="margin-top:4px;font-family:Arial,Helvetica,sans-serif;color:#c9a84c;font-size:10px;letter-spacing:0.3em;text-transform:uppercase;">Advogados Associados</div>
        </td></tr>
        <tr><td style="height:3px;background:#c9a84c;"></td></tr>

