          ${paragrafos}
        </td></tr>

        <tr><td style="border-top:1px solid #e5e0d6;"></td></tr>
        <tr><td style="padding:20px 32px;background:#fafaf7;text-align:center;">
          <p style="margin:0 0 4px 0;font-family:Georgia,'Times New Roman',serif;font-size:13px;color:#0d2a4a;font-weight:600;">Monteiro Ramalho Advogados Associados</p>
